"""Audit the algebra generated by the current digital exchange gates."""
from pathlib import Path
import json
import numpy as np
from scipy.linalg import polar
ROOT=Path(__file__).resolve().parents[2]
files={0.3:ROOT/'results/phase4_3/D40_seq.json',0.6:ROOT/'results/phase4_3/t06_seq.json',0.9:ROOT/'results/phase4_3/t09_seq.json'}
def mat(x):return np.array(x['real'])+1j*np.array(x['imag'])
def ng(U):return U*np.exp(-.5j*np.angle(np.linalg.det(U)))
def favg(U,V):return float((abs(np.trace(V.conj().T@U))**2+2)/6)
U={th:ng(mat(json.loads(p.read_text())['Uodd'])) for th,p in files.items()}
comm=[]
for a in U:
 for b in U:
  if a<b:comm.append({'a':a,'b':b,'commutator_norm':float(np.linalg.norm(U[a]@U[b]-U[b]@U[a]))})
prod=ng(U[.3]@U[.6]);target=U[.9]
out={'commutators':comm,'composition_0.3_plus_0.6_to_0.9':{'matrix_error':float(min(np.linalg.norm(prod-target),np.linalg.norm(prod+target))),'average_fidelity':favg(prod,target)},'conclusion':'All current exchange gates form an effectively diagonal Abelian Z-rotation family. Braiding alone is not universal.'}
p=ROOT/'results/phase4_6/braid_algebra.json';p.parent.mkdir(parents=True,exist_ok=True);p.write_text(json.dumps(out,indent=2));print(json.dumps(out,indent=2))
